import six
from taf.transport.ssh import ssh
from taf.transport.ssh.connection import SSHConnection
from taf.ue.tm500.asc.asc_shell import ASCShell
from taf.ue.tm500.asc.command.selector import CommandsSelector
from taf.ue.tm500.asc.asc_ssh import ASCSSHConnection
from taf.ue.tm500.asc.exception import AlreadyDisconnectedErr, UnexpectedConnectionType


def create_shell(connection):
    asc_connect_obj = ASCSSHConnectionFactory().create(connection=connection)
    return ASCShellFactory().create(connection=asc_connect_obj)


class ASCShellFactory:
    _shell_store = {}

    def create(self, connection):
        self._validate_connection(connection)
        if connection in self._shell_store:
            return self._shell_store[connection]
        return self._create(connection)

    def _validate_connection(self, connection):
        if not connection.is_connected:
            if connection in self._shell_store:
                self._shell_store.pop(connection)
            raise AlreadyDisconnectedErr("connection has been invalid")

    def _create(self, connection):
        command_classes = CommandsSelector(connection).select()
        commands = {name: command_class(connection) for name, command_class in command_classes.items()}
        shell = ASCShell(commands)
        self._shell_store[connection] = shell
        return shell


class ASCConnectionFactory:
    def create(self, **kwargs):
        pass


class ASCSSHConnectionFactory(ASCConnectionFactory):
    _connection_store = {}

    def __init__(self):
        self._robot_ssh_object = ssh()

    def create(self, connection):
        if not connection:
            raise AttributeError("connection must not be None or Empty")

        connection_obj = None
        if isinstance(connection, six.string_types):
            connection_obj = self._robot_ssh_object.get_connection_by_alias(connection)
        elif isinstance(connection, SSHConnection):
            connection_obj = connection
        else:
            raise UnexpectedConnectionType(f"not the expected connection type {type(connection)}")

        if connection in self._connection_store:

            asc_connection_obj = self._connection_store[connection]
            if (connection_obj == asc_connection_obj.ssh_connection) and asc_connection_obj.is_connected:
                return asc_connection_obj
        asc_connection = ASCSSHConnection(connection_obj)
        self._connection_store[connection] = asc_connection
        return asc_connection
